#pragma once

#include <Arduino.h>
#include <Arduino_GFX_Library.h>

// Anti-aliased UTF-8 text with Vietnamese diacritics, blended straight into the
// Arduino_Canvas framebuffer. Fonts are generated by tools/gen_vnfont.py (VnFonts.h).
struct VnGlyph {
    uint16_t code;     // Unicode code point
    uint8_t w, h;      // bitmap size
    int8_t xo, yo;     // bitmap top-left relative to pen position on the baseline
    uint8_t adv;       // pen advance
    uint32_t off;      // offset into the 4-bit alpha bitmap
};

struct VnFont {
    const uint8_t *bitmap;
    const VnGlyph *glyphs;   // sorted by code
    uint16_t count;
    uint8_t lineHeight;
    uint8_t ascent;
    uint8_t descent;
};

namespace VnText {
    // Width in pixels of a UTF-8 string.
    int width(const VnFont &font, const char *text);

    // Draw at pen position (x, baseline). Pixels outside [clipX0, clipX1) are skipped,
    // which the road-name marquee uses to scroll inside its box. Returns the end pen x.
    int draw(Arduino_Canvas *canvas, const VnFont &font, int x, int baseline, const char *text,
             uint16_t color, int clipX0 = 0, int clipX1 = 10000);

    // Centered horizontally on cx.
    void drawCentered(Arduino_Canvas *canvas, const VnFont &font, int cx, int baseline, const char *text,
                      uint16_t color);

    // Right-aligned so the text ends at xRight.
    void drawRight(Arduino_Canvas *canvas, const VnFont &font, int xRight, int baseline, const char *text,
                   uint16_t color);
}
